import{z as i,x as B,o as r,c as l,q as s,j as E,D as e,d as n,s as A,S as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"显示与帧缓冲","description":"","frontmatter":{"title":"显示与帧缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/framebuffer-display.md","filePath":"cs/framebuffer-display.md","lastUpdated":1791063341000}'),p={name:"cs/framebuffer-display.md"};function d(D,a,C,P,_,f){const t=B("Mermaid");return r(),l("div",null,[a[2]||(a[2]=s('<h1 id="显示与帧缓冲" tabindex="-1">显示与帧缓冲 <a class="header-anchor" href="#显示与帧缓冲" aria-label="Permalink to &quot;显示与帧缓冲&quot;">​</a></h1><div class="epigraph"><p>扫描输出按行从内存里的像素阵列取数，时序是行/场同步；CPU 写的是这块缓冲，不是每位去拨显示器引脚。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/i2c-spi-uart">上一课</a>的字节串口画不出栅格。缺口是 <strong>帧缓冲</strong>：线性（或平铺）像素内存 + 扫描 DMA + 显示时序发生器。I²C 往往只剩 DDC 读 EDID。本课不把 GPU 着色器当大模型课，只把「像素从哪来」接到 DMA 与内存层次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CRT 时代的行扫描留下时序：HSYNC/VSYNC、消隐。LCD 仍要这些时序包（或嵌入在 eDP/HDMI 里）。像素格式：32bpp XRGB、YUV。缺口不是 SPI 移位，而是：<strong>带宽</strong> = 分辨率 × 刷新 × 每像素字节，打在 DRAM 通道上，与 CPU 争 <a href="/cs/fr-fcfs">FR-FCFS</a> 队列。双缓冲：扫 A 时 CPU 画 B，交换指针避免撕裂。</p><p><span class="marginnote">数字代入一遍带宽公式：1920×1080、60 Hz、每像素 4 字节，就是 1920×1080×60×4 ≈ 0.5 GB/s；刷新率提到 144 Hz 就超过 1.2 GB/s——而且这是每秒重复读的流量，难怪显示要和 CPU 抢 DRAM 通道。</span></p><p><span class="marginnote">撕裂（tearing）就是屏幕上半部分还是旧帧、下半部分已经是新帧：扫描 DMA 读到一半时 CPU 改了同一块缓冲，画面像被从中间剪开。双缓冲让扫描只看前台，画好的整帧等场消隐的间隙再整体接管。</span></p>',7)),(r(),E(o,null,{default:e(()=>[A(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR_A%5B%22%E5%89%8D%E5%8F%B0%E7%BC%93%E5%86%B2%20A%EF%BC%9A%E6%89%AB%E6%8F%8F%20DMA%20%E6%AD%A3%E5%9C%A8%E8%AF%BB%22%5D%20--%3E%20SCR%5B%22%E6%98%BE%E7%A4%BA%E6%97%B6%E5%BA%8F%E8%BE%93%E5%87%BA%22%5D%0A%20%20CPU2%5B%22CPU%20%E7%94%BB%E4%B8%8B%E4%B8%80%E5%B8%A7%22%5D%20--%3E%20FR_B%5B%22%E5%90%8E%E5%8F%B0%E7%BC%93%E5%86%B2%20B%22%5D%0A%20%20FR_B%20--%3E%20SWAP%7B%22%E7%94%BB%E5%AE%8C%E4%B8%94%E5%A4%84%E4%BA%8E%E6%B6%88%E9%9A%90%3F%22%7D%0A%20%20SWAP%20--%3E%7C%22%E6%98%AF%22%7C%20FLIP%5B%22%E4%BA%A4%E6%8D%A2%E6%8C%87%E9%92%88%EF%BC%9AB%20%E5%8F%98%E5%89%8D%E5%8F%B0%22%5D%0A%20%20SWAP%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E7%AD%89%E4%B8%8B%E4%B8%80%E6%AC%A1%E6%B6%88%E9%9A%90%E5%86%8D%E6%8D%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p>GPU 加速：2D blit 或 3D 管线写帧缓冲，仍是内存。本课不写光栅化算法。</p><h3 id="帧缓冲不是「字符终端的字体-rom」" tabindex="-1">帧缓冲不是「字符终端的字体 ROM」 <a class="header-anchor" href="#帧缓冲不是「字符终端的字体-rom」" aria-label="Permalink to &quot;帧缓冲不是「字符终端的字体 ROM」&quot;">​</a></h3><p>文本模式是另一套字符+属性缓冲；图形模式是像素。把 <code>printf</code> 当帧缓冲 DMA，早期 VGA 文本还能混，高分辨率不行。UEFI GOP 提供线性帧缓冲，下一课固件会用它画启动界面。</p><p><span class="marginnote">Patterson/Hennessy 用像素与刷新讲带宽。CA:AQA 把显示当高带宽 I/O。VESA、HDMI 规范在链路层，本课停在内存侧帧缓冲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配连续或 IOMMU 映射的像素内存。扫描控制器周期性 DMA 读（可 SG）。CPU/GPU 写须考虑缓存：写结合或显式冲刷，否则扫描看到旧行。热插拔：读 EDID（I²C）改时序。与 <a href="/cs/hbm-3d-stack">HBM</a>：独显帧缓冲常在显存，扫描不占主机 DDR。</p>',6)),(r(),E(o,null,{default:e(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%83%8F%E7%B4%A0%E9%98%B5%E5%88%97%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20DMA%22%5D%0A%20%20SCAN%20--%3E%20PHY%5B%22%E6%98%BE%E7%A4%BA%20PHY%20%E6%97%B6%E5%BA%8F%22%5D%0A%20%20CPU%5B%22CPU%2FGPU%20%E5%86%99%22%5D%20--%3E%20PIX%0A%20%20PIX%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9B%BA%E4%BB%B6%20GOP%20%E4%B9%9F%E7%94%A8%E8%BF%99%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>合成（多窗口）在显示控制器或 GPU，仍读多块缓冲。本课钉一块线性缓冲足够。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>启动固件在 DRAM 训练成功后才能设 GOP；之前可能用 UART。PCIe 独显 BAR 映射帧缓冲或命令队列。本课把「人能看见的输出」接到内存与 DMA，结束外设带宽谱：UART → USB → NVMe/显示。</p><p><span class="marginnote">初学者容易以为像素是显示线缆上「实时生成」的——实际上显示器只是照着时序反复读内存里那块像素阵列；内存里是什么就显示什么，没人去写它，屏幕就是静止的一帧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写色彩管理、不重写光刻成像光学、不把 HDMI HDCP 密钥当内容。不进入窗口系统合成器源码。不把显示器当限价簿 GUI。</p><p>后课默认：显示是帧缓冲的周期性 DMA 扫描；带宽打在内存控制器上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>像素在内存；扫描 DMA 按显示时序读出。</li><li>双缓冲防撕裂；格式与刷新决定带宽。</li><li>DDC/EDID 走 I²C，像素不走 I²C。</li><li>出处：Patterson and Hennessy, COD；Hennessy and Patterson, CA:AQA。</li></ul>',9))])}const h=i(p,[["render",d]]);export{m as __pageData,h as default};
